begin;
create extension if not exists pgtap with schema extensions;
select plan(16);
insert into public.hermes_connections(id,company_id,owner_id,address,profile,key_encrypted,state) values ('e0000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','http://localhost','writer','ciphertext','connected');
insert into public.hermes_agents(id,company_id,connection_id,name,speciality,is_default) values ('e1000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000001','Mona','Writing',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select public.send_conversation_message('e2000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','Hello','e3000000-0000-0000-0000-000000000001','run_1');
select public.send_conversation_message('e2000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','Again','e3000000-0000-0000-0000-000000000002','run_2');
select public.send_conversation_message('e2000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','Stop','e3000000-0000-0000-0000-000000000003','run_3');
select ok(not has_function_privilege('authenticated','public.open_conversation_runs(uuid,uuid,bigint)','EXECUTE') and not has_function_privilege('anon','public.open_conversation_runs(uuid,uuid,bigint)','EXECUTE'),'only the service role lists open runs');
select ok(not has_function_privilege('authenticated','public.close_conversation_run(uuid,text,text,text,text,bigint,bigint)','EXECUTE') and not has_function_privilege('anon','public.close_conversation_run(uuid,text,text,text,text,bigint,bigint)','EXECUTE'),'only the service role closes a run');
reset role;
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is((select string_agg(run||':'||person||':'||connection||':'||profile||':'||state,',' order by run) from public.open_conversation_runs()),'run_1:20000000-0000-0000-0000-000000000001:e0000000-0000-0000-0000-000000000001:writer:connected,run_2:20000000-0000-0000-0000-000000000001:e0000000-0000-0000-0000-000000000001:writer:connected,run_3:20000000-0000-0000-0000-000000000001:e0000000-0000-0000-0000-000000000001:writer:connected','every run left open is listed with its person and Connection');
select is((select string_agg(run,',' order by run) from public.open_conversation_runs(null,null,(select min(message) from public.open_conversation_runs()))),'run_2,run_3','the next page starts after the last message seen');
select is((select count(*)::int from public.open_conversation_runs('e2000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000002')),0,'a reader sees only runs of their own conversation');
select is(public.close_conversation_run('e2000000-0000-0000-0000-000000000001','run_1','completed','Hi Omar','session_1',14000,12),true,'a finished run is closed with its reply');
select is(public.close_conversation_run('e2000000-0000-0000-0000-000000000001','run_1','completed','Hi again','session_1',1,1),false,'closing the same run again stores nothing');
select is(public.close_conversation_run('e2000000-0000-0000-0000-000000000001','run_2','lost',null,null,null,null),true,'a run Hermes no longer knows is closed as lost');
select is(public.close_conversation_run('e2000000-0000-0000-0000-000000000001','run_3','stopped',null,null,900,7),true,'a stopped run is closed with what Hermes reported');
-- The service role reads no table: check the record as the database owner, then go on as the service role.
reset role;
select is((select string_agg(author||':'||body,',' order by id) from public.conversation_messages),'person:Hello,person:Again,person:Stop,agent:Hi Omar','only the completed run stores a reply, once');
select is((select string_agg(run_id||':'||outcome||':'||coalesce(input_tokens::text,'unknown')||':'||coalesce(output_tokens::text,'unknown'),',' order by run_id) from public.conversation_usage),'run_1:completed:14000:12,run_2:lost:unknown:unknown,run_3:stopped:900:7','every closed run records its usage once, unknown when Hermes reported none');
select is((select hermes_session_id from public.conversations),'session_1','the Hermes session is recorded');
set local role service_role;
select is((select count(*)::int from public.open_conversation_runs()),0,'no run is left open');
select throws_ok($$select public.close_conversation_run('e2000000-0000-0000-0000-000000000001','run_1','done',null,null,null,null)$$,'22023','conversationFailed','an unknown outcome is refused');
select throws_ok($$select public.close_conversation_run('e2000000-0000-0000-0000-000000000001','run_other','completed','Forged',null,null,null)$$,'P0002','conversationNotFound','only a run of one of the conversation''s messages is closed');
select throws_ok($$select public.close_conversation_run('e2000000-0000-0000-0000-000000000001','run_1','completed',' ',null,null,null)$$,'22023','conversationFailed','a reply needs text');
select * from finish();
rollback;
